def page(fn,title,desc,body):
    nav="".join(f'<li><a href="{h}">{t}</a></li>' for h,t in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} | Blush Studio</title><meta name="description" content="{desc}"><meta property="og:title" content="{title} | Blush Studio"><meta property="og:description" content="{desc}"><meta property="og:image" content="{U(IM['salon'],1200)}">
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;1,400&family=Jost:wght@300;400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body>
<div class="demo-bar">Demo website by Malaak · sample prices, names &amp; contact details</div>
<header><nav class="nav"><a class="logo" href="index.html">BLUSH<span>.</span></a><ul>{nav}</ul><button class="burger" aria-label="Open menu" aria-expanded="false"><span></span><span></span><span></span></button></nav></header>
<main>{body}</main>
<footer><div class="wrap grid g3"><div><a class="logo" href="index.html">BLUSH<span>.</span></a><p style="margin-top:.8rem">A calm, editorial beauty studio for hair, skin and nails.</p></div>
<div><h4>Visit (demo details)</h4><p>Sample Street, Malé, Maldives<br>Sat–Thu 10:00–20:00 · Fri closed</p></div>
<div><h4>Connect</h4><p><a class="wa-link" href="#" target="_blank" rel="noopener">WhatsApp</a> · <a href="https://www.instagram.com/" target="_blank" rel="noopener">Instagram</a><br><a href="tel:+9600000000">+960 000 0000 (demo)</a></p></div></div>
<div class="wrap"><small>© <span class="year"></span> Blush Studio (demonstration brand). Photos: Unsplash. Website design by Malaak.</small></div></footer>
<a class="wa-float wa-link" href="#" target="_blank" rel="noopener" aria-label="Chat on WhatsApp">Chat</a>
<script src="script.js"></script></body></html>'''
def card(s):
    c,cn,n,d,p,t,i=s
    return f'''<article class="card reveal" data-cat="{c}"><div class="ph"><img loading="lazy" src="{U(IM[i],700)}" alt="{n}"></div><p class="meta" style="margin-top:1rem"><span>{cn}</span><span>{t}</span></p><h3>{n}</h3><p>{d}</p><p class="meta"><span>MVR {p:,} <small>(sample)</small></span></p><a class="link" href="booking.html?service={n}">Book this</a></article>'''
